	const root = add(hip, leg.root);
	const [l1, l2, l3] = leg.bones;
	const [r0, r1, r2, r3] = leg.radii;
	let footX = root[0] + leg.rest;
	let lift = 0;
	if (gaitPhase !== null) {
		const t = footTrack((gaitPhase + leg.phase) % 1, sp.duty, stride * sp.duty);
		footX += t.dx;
		lift = t.lift * Math.min(.35, (l1 + l2) * .18);
	}
	const ball = [footX, groundY + r3 + lift];
	const { mid, end } = solve2(root, [ball[0] - Math.cos(leg.footAngle) * l3 * leg.bend, ball[1] + Math.sin(leg.footAngle) * l3], l1, l2, leg.bend);
