		for (let i = 0; i < 3; i++) {
			const x = ballActual[0] + r3 * (.3 + i * .45);
			out.push({
				pts: ellipse(x, g + r3 * .25, r3 * .22, r3 * .2, 0, 12),
				fill: dark,
				alpha: .6
			});
		}
