function bananasOnTheGround() {
	const mm = bananaBunch(3);
	const b = shapesBounds(mm);
	return mapShapes(mm, ([x, y]) => [(x - b.x0) / 1e3, (y - b.y0) / 1e3], 1 / 1e3);
}

